/* ------------------------------------------------------------------
   Clean, confident neo-brutal, dark theme, single accent (teal) plus
   a small set of intentional highlight colors used only where they
   carry meaning (skill category grouping, achievement rank medals).
   Tokens: bg #0D0E14, surface #15161D, ink border/shadow language:
   border = var(--signal) bright teal, shadow = var(--shadow) solid
   dark teal-charcoal (opaque, no blur, no wishy-washy transparency).
   Type: Space Grotesk (display), Inter (body), JetBrains Mono (labels)
------------------------------------------------------------------- */

const FONT_LINK_ID = "hemashree-portfolio-fonts";

function useGoogleFonts() {
  useEffect(() => {
    if (document.getElementById(FONT_LINK_ID)) return;
    const link = document.createElement("link");
    link.id = FONT_LINK_ID;
    link.rel = "stylesheet";
    link.href =
      "https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500;700&display=swap";
    document.head.appendChild(link);
  }, []);
}

function useSmoothScroll() {
  useEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const lenis = new Lenis({
      duration: 1.7,
      easing: (t) => 1 - Math.pow(1 - t, 4),
      smoothWheel: true,
      wheelMultiplier: 0.85,
      touchMultiplier: 1.2,
    });
    let raf;
    function tick(time) {
      lenis.raf(time);
      raf = requestAnimationFrame(tick);
    }
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      lenis.destroy();
    };
  }, []);
}

function useHeroParallax() {
  const copyRef = useRef(null);
  const photoRef = useRef(null);
  useEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const heroEl = document.getElementById("hero");
    if (!heroEl) return;
    let raf;
    const update = () => {
      const rect = heroEl.getBoundingClientRect();
      const heroHeight = heroEl.offsetHeight || window.innerHeight;
      const progress = Math.min(Math.max(-rect.top / heroHeight, 0), 1);
      if (copyRef.current) {
        copyRef.current.style.transform = `translateY(${progress * -30}px)`;
        copyRef.current.style.opacity = String(1 - progress * 0.85);
      }
      if (photoRef.current) {
        photoRef.current.style.transform = `translateY(${progress * -110}px) scale(${1 - progress * 0.16})`;
        photoRef.current.style.opacity = String(1 - progress * 0.7);
        photoRef.current.style.filter = `blur(${progress * 3}px)`;
      }
      raf = requestAnimationFrame(update);
    };
    raf = requestAnimationFrame(update);
    return () => cancelAnimationFrame(raf);
  }, []);
  return { copyRef, photoRef };
}

function useReveal() {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          obs.unobserve(el);
        }
      },
      { threshold: 0.01, rootMargin: "0px 0px -8% 0px" }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return [ref, visible];
}

function Reveal({ children, delay = 0, className = "", style = {}, onClick, onMouseMove }) {
  const [ref, visible] = useReveal();
  return (
    <div
      ref={ref}
      className={className}
      onClick={onClick}
      onMouseMove={onMouseMove}
      style={{
        ...style,
        opacity: visible ? 1 : 0,
        transform: visible ? "translateY(0px)" : "translateY(26px)",
        transition: `opacity 0.4s cubic-bezier(.16,1,.3,1) ${delay}s, transform 0.4s cubic-bezier(.16,1,.3,1) ${delay}s`,
      }}
    >
      {children}
    </div>
  );
}

function useScrollProgress() {
  const [progress, setProgress] = useState(0);
  useEffect(() => {
    const handler = () => {
      const scrollTop = window.scrollY;
      const height = document.documentElement.scrollHeight - window.innerHeight;
      setProgress(height > 0 ? (scrollTop / height) * 100 : 0);
    };
    window.addEventListener("scroll", handler, { passive: true });
    handler();
    return () => window.removeEventListener("scroll", handler);
  }, []);
  return progress;
}

function useActiveSection(ids) {
  const [active, setActive] = useState(ids[0]);
  useEffect(() => {
    const observers = ids.map((id) => {
      const el = document.getElementById(id);
      if (!el) return null;
      const obs = new IntersectionObserver(
        ([entry]) => {
          if (entry.isIntersecting) setActive(id);
        },
        { rootMargin: "-42% 0px -52% 0px", threshold: 0 }
      );
      obs.observe(el);
      return obs;
    });
    return () => observers.forEach((o) => o && o.disconnect());
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return active;
}

function useTilt(maxDeg = 7) {
  const ref = useRef(null);
  const handleMove = (e) => {
    const el = ref.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width - 0.5;
    const y = (e.clientY - rect.top) / rect.height - 0.5;
    el.style.setProperty("--rx", `${(-y * maxDeg).toFixed(2)}deg`);
    el.style.setProperty("--ry", `${(x * maxDeg).toFixed(2)}deg`);
  };
  const handleLeave = () => {
    const el = ref.current;
    if (!el) return;
    el.style.setProperty("--rx", "0deg");
    el.style.setProperty("--ry", "0deg");
  };
  return { ref, onMouseMove: handleMove, onMouseLeave: handleLeave };
}

function handleSpotlightMove(e) {
  const el = e.currentTarget;
  const rect = el.getBoundingClientRect();
  el.style.setProperty("--sx", `${e.clientX - rect.left}px`);
  el.style.setProperty("--sy", `${e.clientY - rect.top}px`);
}

function HeroGlow() {
  const glowRef = useRef(null);
  const handleMove = (e) => {
    const el = glowRef.current;
    if (!el) return;
    const rect = e.currentTarget.getBoundingClientRect();
    el.style.setProperty("--gx", `${e.clientX - rect.left}px`);
    el.style.setProperty("--gy", `${e.clientY - rect.top}px`);
    el.style.opacity = "1";
  };
  const handleLeave = () => {
    const el = glowRef.current;
    if (!el) return;
    el.style.opacity = "0";
  };
  return (
    <div
      className="hm-hero-glow-catcher"
      onMouseMove={handleMove}
      onMouseLeave={handleLeave}
      aria-hidden="true"
    >
      <div ref={glowRef} className="hm-hero-glow" />
    </div>
  );
}

function AnimatedCounter({ value, suffix = "", duration = 1000 }) {
  const [display, setDisplay] = useState(0);
  const [ref, visible] = useReveal();
  useEffect(() => {
    if (!visible) return;
    let start = null;
    let raf;
    const step = (ts) => {
      if (!start) start = ts;
      const progress = Math.min((ts - start) / duration, 1);
      setDisplay(Math.floor(progress * value));
      if (progress < 1) raf = requestAnimationFrame(step);
      else setDisplay(value);
    };
    raf = requestAnimationFrame(step);
    return () => raf && cancelAnimationFrame(raf);
  }, [visible, value, duration]);
  return (
    <span ref={ref}>
      {display}
      {suffix}
    </span>
  );
}

function StatusDot() {
  return <span className="hm-status-dot" aria-hidden="true" />;
}

const EXPLOSION_COLORS = ["#8B7FE8", "#5EC8D8", "#B48EE0", "#6FA8E0", "#7FD4C1"];

function NeuralHero() {
  const canvasRef = useRef(null);
  const stateRef = useRef({ nodes: [], bursts: [], w: 0, h: 0, dpr: 1 });
  const reducedRef = useRef(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    reducedRef.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const resize = () => {
      const parent = canvas.parentElement;
      const w = parent.clientWidth;
      const h = parent.clientHeight;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = w * dpr;
      canvas.height = h * dpr;
      canvas.style.width = w + "px";
      canvas.style.height = h + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const s = stateRef.current;
      s.w = w;
      s.h = h;
      s.dpr = dpr;
      const count = Math.max(45, Math.min(100, Math.floor((w * h) / 11000)));
      s.nodes = Array.from({ length: count }).map(() => ({
        x: Math.random() * w,
        y: Math.random() * h,
        vx: (Math.random() - 0.5) * 0.22,
        vy: (Math.random() - 0.5) * 0.22,
        r: 1.3 + Math.random() * 1.3,
        pulse: Math.random() * Math.PI * 2,
      }));
    };
    resize();
    window.addEventListener("resize", resize);

    const spawnBurst = (x, y, big) => {
      const color = EXPLOSION_COLORS[Math.floor(Math.random() * EXPLOSION_COLORS.length)];
      const n = big ? 42 : 30;
      const particles = Array.from({ length: n }).map((_, i) => {
        const angle = (Math.PI * 2 * i) / n + Math.random() * 0.35;
        const speed = (big ? 2 : 1.5) + Math.random() * (big ? 4.2 : 3);
        return {
          x, y,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          life: 1,
          decay: 0.01 + Math.random() * 0.012,
          size: 1.6 + Math.random() * 2.8,
          color,
        };
      });
      stateRef.current.bursts.push(...particles);
      stateRef.current.bursts.push({ x, y, ring: true, life: 1, decay: 0.026, size: 4, color });
      stateRef.current.bursts.push({ x, y, ring: true, life: 1, decay: 0.036, size: 2, color: "#FFD166" });
    };

    const handlePointer = (e) => {
      const rect = canvas.getBoundingClientRect();
      const cx = (e.touches ? e.touches[0].clientX : e.clientX) - rect.left;
      const cy = (e.touches ? e.touches[0].clientY : e.clientY) - rect.top;
      spawnBurst(cx, cy, true);
    };
    canvas.addEventListener("pointerdown", handlePointer);

    // ambient auto-sparks so it stays alive even without interaction
    const autoSpark = setInterval(() => {
      if (reducedRef.current) return;
      const s = stateRef.current;
      if (!s.w || !s.h) return;
      spawnBurst(Math.random() * s.w, Math.random() * s.h, false);
    }, 4200);

    let raf;
    const tick = () => {
      const s = stateRef.current;
      ctx.clearRect(0, 0, s.w, s.h);

      for (const n of s.nodes) {
        n.x += n.vx;
        n.y += n.vy;
        n.pulse += 0.03;
        if (n.x < 0 || n.x > s.w) n.vx *= -1;
        if (n.y < 0 || n.y > s.h) n.vy *= -1;
      }
      ctx.lineWidth = 1;
      for (let i = 0; i < s.nodes.length; i++) {
        for (let j = i + 1; j < s.nodes.length; j++) {
          const a = s.nodes[i], b = s.nodes[j];
          const dx = a.x - b.x, dy = a.y - b.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist < 170) {
            ctx.strokeStyle = `rgba(200,210,255,${0.34 * (1 - dist / 160)})`;
            ctx.beginPath();
            ctx.moveTo(a.x, a.y);
            ctx.lineTo(b.x, b.y);
            ctx.stroke();
          }
        }
      }
      for (const n of s.nodes) {
        const glow = 0.5 + Math.sin(n.pulse) * 0.3;
        ctx.beginPath();
        ctx.arc(n.x, n.y, n.r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(210,218,255,${0.55 + glow * 0.3})`;
        ctx.shadowColor = "rgba(210,218,255,0.65)";
        ctx.shadowBlur = 6;
        ctx.fill();
        ctx.shadowBlur = 0;
      }

      s.bursts = s.bursts.filter((p) => p.life > 0);
      for (const p of s.bursts) {
        if (p.ring) {
          p.size += 3.4;
          p.life -= p.decay;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
          ctx.strokeStyle = p.color + Math.floor(p.life * 90).toString(16).padStart(2, "0");
          ctx.lineWidth = 2;
          ctx.stroke();
          continue;
        }
        p.x += p.vx;
        p.y += p.vy;
        p.vx *= 0.96;
        p.vy *= 0.96;
        p.life -= p.decay;
        ctx.beginPath();
        ctx.arc(p.x, p.y, Math.max(0.4, p.size * p.life), 0, Math.PI * 2);
        ctx.fillStyle = p.color + Math.floor(Math.max(0, p.life) * 255).toString(16).padStart(2, "0");
        ctx.fill();
      }

      raf = requestAnimationFrame(tick);
    };
    if (!reducedRef.current) {
      raf = requestAnimationFrame(tick);
    } else {
      tick();
    }

    return () => {
      window.removeEventListener("resize", resize);
      canvas.removeEventListener("pointerdown", handlePointer);
      clearInterval(autoSpark);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  return (
    <div className="hm-neural-layer" aria-hidden="true">
      <canvas ref={canvasRef} className="hm-neural-canvas" />
    </div>
  );
}

