function Marquee() {
  const items = [...MARQUEE_WORDS, ...MARQUEE_WORDS];
  return (
    <div className="hm-marquee-row">
      <div className="hm-marquee-track">
        {items.map((word, i) => (
          <span key={i}>
            {word}
            <i className="hm-marquee-dot" />
          </span>
        ))}
      </div>
    </div>
  );
}

function ContactForm() {
  const [form, setForm] = useState({ name: "", email: "", subject: "", message: "" });
  const [sent, setSent] = useState(false);
  const update = (key) => (e) => setForm((f) => ({ ...f, [key]: e.target.value }));

  const handleSubmit = (e) => {
    e.preventDefault();
    const body = encodeURIComponent(
      `${form.message}\n\n— ${form.name} (${form.email})`
    );
    const subject = encodeURIComponent(form.subject || "Portfolio contact");
    window.location.href = `mailto:ysbhema@gmail.com?subject=${subject}&body=${body}`;
    setSent(true);
  };

  return (
    <form className="hm-form" onSubmit={handleSubmit}>
      <label className="hm-form-field">
        <span className="hm-mono">Your Name</span>
        <input type="text" placeholder="John Doe" value={form.name} onChange={update("name")} required />
      </label>
      <label className="hm-form-field">
        <span className="hm-mono">Your Email</span>
        <input type="email" placeholder="john@example.com" value={form.email} onChange={update("email")} required />
      </label>
      <label className="hm-form-field">
        <span className="hm-mono">Subject</span>
        <input type="text" placeholder="Project Opportunity / Collaboration" value={form.subject} onChange={update("subject")} />
      </label>
      <label className="hm-form-field">
        <span className="hm-mono">Message</span>
        <textarea rows={5} placeholder="Hi Hemashree, I saw your portfolio and would love to discuss..." value={form.message} onChange={update("message")} required />
      </label>
      <button type="submit" className="hm-btn hm-btn-primary hm-form-submit hm-btn-lime">
        {sent ? "Opening your email app…" : "Send Message"} <Send size={15} />
      </button>
    </form>
  );
}

function Section({ id, children, className = "" }) {
  return (
    <section id={id} className={`hm-section ${className}`}>
      <div className="hm-section-inner">{children}</div>
    </section>
  );
}

